from typing import Dict

class ConfigModifier:
    def __init__(self, config_file: str, placeholders: Dict[str, str]):
        self.config_file = config_file
        self.placeholders = placeholders

    def modify_config(self) -> None:
        try:
            # Construct the sed command to replace all placeholders in the config file
            for placeholder, value in self.placeholders.items():
                sed_command = f'sed -i ""s/{placeholder}/{value}/g"" {self.config_file}'
                subprocess.run(sed_command.split(), check=True)

            # Add new line with encrypted password using sed command
            password_encryption_command = f'sed -i ""$a\\nEncryptedPassword"" {self.config_file}'
            subprocess.run(password_encryption_command.split(), check=True)

            print(""Config file modified successfully."")
        except subprocess.CalledProcessError as e:
            print(f""Failed to modify config file: {e}"")
        except Exception as e:
            print(f""An error occurred: {e}"")

