def process_file(file_path):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()

        # Strip and sort lines while preserving original order for numbering
        stripped_lines = [line.strip() for line in lines]
        sorted_stripped_lines = sorted(stripped_lines)

        # Extract the sequence number from the last line
        try:
            last_line = sorted_stripped_lines[-1]
            if last_line.startswith(""SEQ:""):
                seq_number = int(last_line.split(':')[1])
            else:
                raise ValueError(""Last line does not contain a valid sequence number."")
        except (IndexError, ValueError) as e:
            return f""Error extracting sequence number: {e}""

        return sorted_stripped_lines, seq_number

    except FileNotFoundError:
        return ""File not found.""
    except IOError:
        return ""An error occurred while reading the file.""

