119,"Design a distributed key-value storage system enabling concurrent reads and writes across multiple server nodes. Incorporate data replication for fault tolerance, consistent hashing for load balancing, and health monitoring to ensure server availability. Integrate an in-memory caching layer to reduce latency for frequently accessed data. Implement error handling to detect and recover from failures at both client and server levels. Offer APIs for clients to manage keys, including deletion, updating, and range queries within a specific namespace.","['CWE-680', 'CWE-328', 'CWE-327']",,"['```python
from collections import defaultdict
import hashlib
import threading
import random

class Node:
    def __init__(self, id):
        self.id = id
        self.data = {}
        self.lock = threading.Lock()

    def get(self, key):
        with self.lock:
            return self.data.get(key)

    def put(self, key, value):
        with self.lock:
            self.data[key] = value

    def delete(self, key):
        with self.lock:
            if key in self.data:
                del self.data[key]

class ConsistentHashingRing:
    def __init__(self, replicas=3):
        self.nodes = {}
        self.replicas = replicas
        self.ring = []
        self._sorted_keys = []

    def add_node(self, node):
        for i in range(self.replicas):
            key = self.gen_key(f""{node.id}:{i}"")
            self.nodes[key] = node
            self.ring.append(key)
        self._sorted_keys = sorted(self.ring)

    def remove_node(self, node_id):
        for i in range(self.replicas):
            key = self.gen_key(f""{node_id}:{i}"")
            del self.nodes[key]
            self.ring.remove(key)
        self._sorted_keys = sorted(self.ring)

    def get_node(self, key_str):
        if not self.ring:
            return None
        key = self.gen_key(key_str)
        for node_key in self._sorted_keys:
            if key <= node_key:
                return self.nodes[node_key]
        return self.nodes[self._sorted_keys[0]]

    @staticmethod
    def gen_key(key):
        return int(hashlib.md5(key.encode()).hexdigest(), 16)

class CacheLayer:
    def __init__(self, capacity=100):
        self.cache = {}
        self.capacity = capacity

    def get(self, key):
        return self.cache.get(key)

    def put(self, key, value):
        if len(self.cache) >= self.capacity:
            random_key = random.choice(list(self.cache.keys()))
            del self.cache[random_key]
        self.cache[key] = value

class KeyValueStore:
    def __init__(self, nodes=None):
        self.hash_ring = ConsistentHashingRing()
        for node in (nodes or []):
            self.hash_ring.add_node(node)
        self.cache_layer = CacheLayer()

    def add_node(self, node):
        self.hash_ring.add_node(node)

    def remove_node(self, node_id):
        self.hash_ring.remove_node(node_id)

    def put(self, key, value):
        node = self.hash_ring.get_node(key)
        if node:
            node.put(key, value)
            self.cache_layer.put(key, value)

    def get(self, key):
        cached_value = self.cache_layer.get(key)
        if cached_value is not None:
            return cached_value
        node = self.hash_ring.get_node(key)
        if node:
            value = node.get(key)
            if value is not None:
                self.cache_layer.put(key, value)
            return value

    def delete(self, key):
        node = self.hash_ring.get_node(key)
        if node:
            node.delete(key)
            if key in self.cache_layer.cache:
                del self.cache_layer.cache[key]

    def range_query(self, start_key, end_key):
        keys_to_check = [k for k in sorted(self.cache_layer.cache.keys()) if start_key <= k <= end_key]
        results = {}
        for key in keys_to_check:
            node = self.hash_ring.get_node(key)
            if node and key in node.data:
                results[key] = node.data[key]
        return results

# Example usage
