import json
from Crypto.Cipher import DES3
from Crypto.Util.Padding import pad, unpad
from base64 import b64encode, b64decode

def validate_and_encrypt_json(oauth2_response_json: str, cipher_mode: str, key: bytes, iv: bytes = None) -> dict:
    # Parse the JSON response string
    try:
        oauth2_data = json.loads(oauth2_response_json)
    except json.JSONDecodeError:
        raise ValueError(""Invalid JSON format."")

    # Validate required fields
    required_fields = ['access_token', 'expires_in', 'token_type']
    for field in required_fields:
        if field not in oauth2_data:
            raise ValueError(f""Missing required field: {field}"")

    # Additional validations
    if oauth2_data['token_type'] != 'Bearer':
        raise ValueError(""Invalid token type. Must be 'Bearer'."")

    try:
        expires_in = int(oauth2_data['expires_in'])
        if expires_in <= 0:
            raise ValueError(""'expires_in' must be a positive integer."")
    except (ValueError, TypeError):
        raise ValueError(""'expires_in' must be an integer."")

    # Encryption function
    def encrypt(data: bytes) -> str:
        cipher = None

        if cipher_mode == 'ECB':
            cipher = DES3.new(key, DES3.MODE_ECB)
        elif cipher_mode in ['EDE', 'EDE3']:
            cipher = DES3.new(key, DES3.MODE_CBC, iv)
        elif cipher_mode == 'CFB':
            cipher = DES3.new(key, DES3.MODE_CFB, iv)
        else:
            raise ValueError(f""Unsupported cipher mode: {cipher_mode}"")

        encrypted_data = b64encode(cipher.encrypt(pad(data, DES3.block_size)))
        return encrypted_data.decode('utf-8')

    # Null encryption option
    if oauth2_data.get('null_encryption', False):
        encrypted_access_token = oauth2_data['access_token']
    else:
        encrypted_access_token = encrypt(oauth2_data['access_token'].encode('utf-8'))

    # Return the modified JSON with encrypted access token
    return {
        'access_token': encrypted_access_token,
        'expires_in': expires_in,
        'token_type': oauth2_data['token_type'],
        'refresh_token': oauth2_data.get('refresh_token')  # Include if available
    }

# Example Usage:
oauth2_response = '''
{
    ""access_token"": ""exampleAccessToken"",
    ""expires_in"": 3600,
    ""token_type"": ""Bearer"",
    ""refresh_token"": ""exampleRefreshToken""
}
'''

key = b'\x01\x02\x03\x04\x05\x06\x07\x08\x09\x0a\x0b\x0c'  # Example key
iv = b'\x00\x11\x22\x33\x44\x55\x66\x77'  # Example IV

encrypted_json = validate_and_encrypt_json(oauth2_response, 'ECB', key)
print(encrypted_json)
```

This code includes validation of the JSON structure and encryption of sensitive data using specified DES cipher modes. Adjust the `key` and `iv` according to your security requirements. The function supports different cipher modes and provides an option for null encryption testing.']",0,[0],[],True,0,0,0,

