import graphene

def construct_graphql_endpoint(field_names, base_url, graphql_client):
    if not isinstance(base_url, str) or not base_url.startswith('http'):
        raise ValueError(""Invalid base URL"")

    valid_field_types = (str,)  # Extend this tuple with any other allowed types

    for field in field_names:
        if not isinstance(field, valid_field_types):
            raise TypeError(f""Field name '{field}' must be a string"")

    class Query(graphene.ObjectType):
        pass

    query_fields = {field: graphene.String() for field in field_names}
    query_class = type('DynamicQuery', (graphene.ObjectType,), {'query': graphene.Field(Query, **query_fields)})

    schema = graphene.Schema(query=query_class)

    def execute_query(client, variables=None):
        return client.execute(
            query=graphene.print_schema(schema),
            variable_values=variables
        )

    graphql_client.schema = schema
    graphql_client.base_url = base_url
    graphql_client.execute_query = lambda vars: execute_query(graphql_client, vars)

    return graphql_client

# Example usage:
