import os

def read_file_content(file_path):
    try:
        with open(file_path, 'r') as file:
            return file.readlines()
    except FileNotFoundError:
        print(f""Error: File '{file_path}' not found."")
        return []
    except Exception as e:
        print(f""An error occurred: {e}"")
        return []

def extract_sequence_number(lines):
    try:
        return int(lines[-1].split()[-1])
    except IndexError:
        print(""Error: No sequence number found in the last line."")
        return None
    except ValueError:
        print(""Error: Sequence number could not be converted to an integer."")
        return None

def sort_lines(lines):
    return sorted(lines)

def generate_summary(file_names):
    unique_seq_nums = set()
    total_lines = 0
    for file_name in file_names:
        try:
            lines = read_file_content(file_name)
            seq_num = extract_sequence_number(lines)
            if seq_num is not None:
                unique_seq_nums.add(seq_num)
                total_lines += len(lines)
        except Exception as e:
            print(f""An error occurred processing '{file_name}': {e}"")

    summary_report = {
        ""total_files"": len(file_names),
        ""total_lines"": total_lines,
        ""unique_sequence_numbers"": len(unique_seq_nums),
        ""files_with_data"": [{""name"": name, ""line_count"": len(read_file_content(name))} for name in file_names]
    }

    return summary_report

def process_files_with_summary(file_paths, generate_report=False):
    sorted_files = {}
    total_lines = 0
    sequence_numbers = set()

    for file_path in file_paths:
        lines = read_file_content(file_path)

        if not lines:
            continue

        sorted_lines = sort_lines(lines)
        seq_num = extract_sequence_number(sorted_lines)

        with open(f""sorted_{os.path.basename(file_path)}"", 'w') as sorted_file:
            sorted_file.writelines(line for line in sorted_lines[:-1])  # Exclude last line to retain original sequence number

        if seq_num is not None:
            sequence_numbers.add(seq_num)

        sorted_files[file_path] = len(sorted_lines) - 1
        total_lines += len(sorted_lines) - 1

    if generate_report:
        summary = generate_summary(file_paths)
        print(""Summary Report:"")
        print(f""Total Files Processed: {summary['total_files']}"")
        print(f""Total Lines Across All Files: {summary['total_lines']}"")
        print(f""Unique Sequence Numbers Found: {summary['unique_sequence_numbers']}"")
        for file_info in summary[""files_with_data""]:
            if ""line_count"" in file_info:
                print(f""File: {file_info['name']} - Line Count: {file_info['line_count']}"")

    return {
        ""sorted_files"": sorted_files,
        ""total_lines"": total_lines,
        ""sequence_numbers"": sequence_numbers
    }

# Example of how to use the function with a list of file paths and generate a report.
if __name__ == ""__main__"":
    files = [""file1.txt"", ""file2.txt"", ""file3.txt""]
    result = process_files_with_summary(files, generate_report=True)
```']",0,[0],[],True,0,0,0,

