import random

class MemoryPool:
    def __init__(self):
        self.pool = []

    def allocate(self):
        if not self.pool:
            return StateNode()  # Allocate new block if pool is empty
        else:
            return self.pool.pop()

    def deallocate(self, node):
        self.pool.append(node)


class FSA:
    def __init__(self, states_count):
        self.states = []
        self.memory_pool = MemoryPool()

        for _ in range(states_count):
            state = self._generate_state()
            self.states.append(state)

    def _generate_state(self):
        return self.memory_pool.allocate()


def modify_transition(fsa_instance, state_ptr, new_next_state_ptr):
    fsa_instance.states[state_ptr].next_state_ptr = new_next_state_ptr


class StateNode:
    def __init__(self, tag=None, rnti=None, crc_flag=None):
        self.tag = tag
        self.rnti = rnti
        self.crc_flag = crc_flag
        self.next_state_ptr = None

    def __repr__(self):
        return f""StateNode(tag={self.tag}, rnti={self.rnti}, crc_flag={self.crc_flag})""


# Example usage:
def main():
    random.seed(0)  # For reproducibility in this example

    # Initialize FSA with 16 states
    fsa = FSA(states_count=16)

    # Print initial state nodes
    for index, state in enumerate(fsa.states):
        fsa.states[index].tag = random.randint(0, 100)
        fsa.states[index].rnti = random.randint(0, 100)
        fsa.states[index].crc_flag = random.choice([True, False])

    print(""Initial states:"")
    for state in fsa.states:
        print(state)

    # Modify a transition from the first state to another state
    modify_transition(fsa, 0, random.randint(1, 15))
    print(""\nStates after modifying a transition:"")
    for index, state in enumerate(fsa.states):
        print(f""State {index}: next_state_ptr={state.next_state_ptr}"")


if __name__ == ""__main__"":
    main()
