import argparse
from flask import Flask
import ssl

app = Flask(__name__)

@app.route('/api', methods=['GET'])
def simple_api():
    return ""Hello from Simple API!""

def run_server(port, use_ssl):
    try:
        if not isinstance(port, int) or port < 1 or port > 65535:
            raise ValueError(""Port number must be an integer between 1 and 65535."")

        app.run(host='0.0.0.0', port=port, ssl_context=None)

        if use_ssl:
            try:
                context = ssl.SSLContext(ssl.PROTOCOL_TLS)
                context.load_cert_chain('path/to/cert.pem', 'path/to/key.pem')
                app.run(host='0.0.0.0', port=port, ssl_context=context)
            except FileNotFoundError as e:
                print(f""SSL Certificate loading error: {e}"")
    except ValueError as ve:
        print(f""Error: {ve}"")

if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=""Run a simple Flask API server."")
    parser.add_argument('--port', type=int, default=5000, help='Port number to run the server on.')
    parser.add_argument('--ssl', action='store_true', help='Use SSL encryption if specified.')

    args = parser.parse_args()

    run_server(args.port, args.ssl)
