import json

def parse_json_file(file_path):
    try:
        with open(file_path, 'r') as file:
            data = json.load(file)

        def get_type(value):
            if isinstance(value, dict):
                return {k: get_type(v) for k, v in value.items()}
            elif isinstance(value, list):
                return [get_type(item) for item in value]
            else:
                return type(value).__name__

        result = {}

        if isinstance(data, dict):
            for key, value in data.items():
                result[key] = get_type(value)
        elif isinstance(data, list):
            for i, item in enumerate(data):
                result[str(i)] = get_type(item)
        else:
            return ""Invalid JSON structure: Expected a dictionary or list at the root.""

        return result

    except json.JSONDecodeError:
        return ""Error: Invalid JSON file.""
    except FileNotFoundError:
        return f""Error: File not found '{file_path}'.""
    except Exception as e:
        return f""Error: {str(e)}""

# Example usage
