    with threading.Lock():
        if rnti in rntis:
            rntis.remove(rnti)
            return jsonify({'success': True, 'message': f'RNTI {rnti} removed'}), 200
        else:
            return jsonify({'error': 'RNTI not found'}), 404

@app.errorhandler(500)
