# Distributed Key-Value Storage System

import hashlib
from collections import defaultdict
import threading
import time
import json
from concurrent.futures import ThreadPoolExecutor

# 1. Consistent Hashing with Virtual Nodes
class ConsistentHashRing:
    def __init__(self, nodes=None):
        self.ring = dict()
        self.sorted_keys = []
        self.nodes = set(nodes or [])

    def _hash(self, key):
        return int(hashlib.md5(key.encode('utf-8')).hexdigest(), 16)

    def add_node(self, node):
        for i in range(100): # virtual nodes
            hashed_key = self._hash(f""{node}:{i}"")
            self.ring[hashed_key] = node
            self.sorted_keys.append(hashed_key)
        self.sorted_keys.sort()

    def remove_node(self, node):
        for i in range(100): 
            hashed_key = self._hash(f""{node}:{i}"")
            del self.ring[hashed_key]
            self.sorted_keys.remove(hashed_key)

    def get_node(self, key):
        if not self.ring:
            return None
        hashed_key = self._hash(key)
        index = next(i for i in range(len(self.sorted_keys)) if self.sorted_keys[i] > hashed_key) % len(self.sorted_keys)
        return self.ring[self.sorted_keys[index]]

    def rebalance_nodes(self, new_nodes):
        current_nodes = set(self.nodes)
        nodes_to_add = new_nodes - current_nodes
        nodes_to_remove = current_nodes - new_nodes

        for node in nodes_to_remove:
            self.remove_node(node)

        for node in nodes_to_add:
            self.add_node(node)

# 2. Scalable In-Memory Caching with Bloom Filters
class BloomFilter:
    def __init__(self, size, hash_count):
        self.size = size
        self.hash_count = hash_count
        self.bit_array = [0] * size

    def _hashes(self, key):
        return [(int(hashlib.md5((key + str(i)).encode()).hexdigest(), 16) % self.size) for i in range(self.hash_count)]

    def add(self, item):
        for hash_code in self._hashes(item):
            self.bit_array[hash_code] = 1

    def check(self, item):
        return all(self.bit_array[hash_code] for hash_code in self._hashes(item))

class Cache:
    def __init__(self, capacity=100):
        self.capacity = capacity
        self.cache = {}
        self.access_times = []

    # LFU caching strategy
    def lfu_eviction(self):
        if len(self.cache) > self.capacity:
            least_frequent_key = min(self.cache.keys(), key=lambda k: self.cache[k][1])
            del self.cache[least_frequent_key]

    # LRU caching strategy
    def lru_eviction(self):
        if len(self.cache) > self.capacity:
            oldest_accessed_key = self.access_times.pop(0)
            del self.cache[oldest_accessed_key]

    def get(self, key):
        if key in self.cache:
            self.access_times.remove(key)
            self.access_times.append(key)
            return self.cache[key][0]
        else:
            return None

    def put(self, key, value):
        if len(self.cache) >= self.capacity:
            self.lru_eviction()

        self.cache[key] = (value, 1) # frequency count
        self.access_times.append(key)

