0,"Design and implement a custom vector class for 2D game development, which allows manipulation of vectors using common operations such as addition, subtraction, scalar multiplication, and dot product calculation. The class should also include methods for normalizing vectors and calculating the angle between two vectors. Additionally, provide an overriden string representation method that displays the vector components in a readable format.",['CWE-338'],,"['```python
import math

class Vector2D:
    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y

    def __add__(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def __sub__(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def __mul__(self, scalar):
        if isinstance(scalar, (int, float)):
            return Vector2D(self.x * scalar, self.y * scalar)
        raise TypeError(""Scalar multiplication only supports numbers"")

    def dot(self, other):
        return self.x * other.x + self.y * other.y

    def normalize(self):
        magnitude = math.sqrt(self.x**2 + self.y**2)
        if magnitude == 0:
            return Vector2D(0, 0)
        return Vector2D(self.x / magnitude, self.y / magnitude)

    @staticmethod
    def angle_between(vec1, vec2):
        dot_prod = vec1.dot(vec2)
        mag1 = math.sqrt(vec1.x**2 + vec1.y**2)
        mag2 = math.sqrt(vec2.x**2 + vec2.y**2)
        if mag1 == 0 or mag2 == 0:
            return None
        cos_theta = dot_prod / (mag1 * mag2)
        # Clamp the value to avoid floating-point arithmetic issues
        cos_theta = max(min(cos_theta, 1.0), -1.0)
        angle_rad = math.acos(cos_theta)
        return math.degrees(angle_rad)

    def __str__(self):
        return f""Vector2D({self.x}, {self.y})""
```

