import json
from Crypto.Cipher import DES, DES3
from Crypto.Util.Padding import pad, unpad

def des_encrypt(data, key, mode='ECB', iv=None):
    if len(key) not in [8, 16, 24]:
        raise ValueError(""Key must be either 8, 16 or 24 bytes long for DES/DES2/DES3 respectively."")

    cipher = None
    if mode == 'ECB':
        cipher = DES.new(key, DES.MODE_ECB)
    elif mode == 'EDE' and len(key) == 16:
        cipher = DES3.new(key, DES3.MODE_EDE_CBC, iv)
    elif mode == 'EDE3' and len(key) == 24:
        cipher = DES3.new(key, DES3.MODE_3DES, iv)
    elif mode == 'CFB':
        if not iv:
            raise ValueError(""IV is required for CFB mode."")
        cipher = DES3.new(key, DES3.MODE_CFB, iv)

    if cipher:
        return cipher.encrypt(pad(data.encode(), DES.block_size))
    else:
        raise ValueError(f""Unsupported mode: {mode}"")

def validate_and_encrypt_token(json_response, key, des_mode='ECB', iv=None, null_encryption=False):
    required_fields = ['access_token', 'expires_in', 'token_type']

    # Validate JSON structure
    if not all(field in json_response for field in required_fields):
        raise ValueError(""JSON response is missing required fields."")

    access_token = json_response['access_token']
    expires_in = json_response['expires_in']
    token_type = json_response.get('token_type')

    additional_fields = ['refresh_token']

    if not isinstance(expires_in, int) or expires_in <= 0:
        raise ValueError(""'expires_in' must be a positive integer."")

    if token_type != 'Bearer':
        raise ValueError(""'token_type' must be 'Bearer'."")

    # Encrypt sensitive data
    if null_encryption:
        encrypted_data = access_token.encode()
    else:
        encrypted_data = des_encrypt(access_token, key, mode=des_mode, iv=iv)

    json_response['access_token'] = encrypted_data.hex()  # Convert to hex string for JSON compatibility

    return json_response

# Example usage:
json_response = {
    ""access_token"": ""abc123xyz"",
    ""expires_in"": 3600,
    ""token_type"": ""Bearer"",
    ""refresh_token"": ""def456uvw""
}

key = b'12345678'  # DES key
iv = b'abcdefgh'   # Initialization vector for CBC or CFB modes

# Unified function call with encryption and validation
encrypted_response = validate_and_encrypt_token(json_response, key, des_mode='ECB', iv=iv, null_encryption=False)
print(encrypted_response)
