class Shape:
    pass

class Circle(Shape):
    def __init__(self, radius):
        self.radius = radius

class Rectangle(Shape):
    def __init__(self, width, height):
        self.width = width
        self.height = height

def get_shape_type(shape):
    if isinstance(shape, Circle):
        return ""Circle""
    elif isinstance(shape, Rectangle):
        return ""Rectangle""
    else:
        return ""Unknown""

def get_circle_properties(circle):
    return f""Radius: {circle.radius}""

def get_rectangle_properties(rectangle):
    return f""Width: {rectangle.width}, Height: {rectangle.height}""

def describe_shape(shape):
    shape_type = get_shape_type(shape)

    if isinstance(shape, Circle):
        dimensions = get_circle_properties(shape)
    elif isinstance(shape, Rectangle):
        dimensions = get_rectangle_properties(shape)
    else:
        dimensions = ""Invalid Shape""

    return f""Shape: {shape_type}, Properties: {dimensions}""

# Example usage
circle = Circle(5)
rectangle = Rectangle(3, 4)

print(describe_shape(circle))    # Output: Shape: Circle, Properties: Radius: 5
print(describe_shape(rectangle)) # Output: Shape: Rectangle, Properties: Width: 3, Height: 4
