def generate_random_signal_parameters():
    return {
        'rssi': np.random.normal(100.0, 20.0),
        'ecno': np.random.normal(15.0, 3.0),
        'ci': np.random.normal(35.0, 15.0)
    }

def validate_message(message, scenario_cell_type):
    if message.cell_id > 999 or message.cell_id < 1:
        return False

    if message.bcch_n_radio_network > 99 or message.bcch_n_radio_network < 1:
        return False

    if not isinstance(message.tx_status, int) or not (message.tx_status == 0 or message.tx_status == 1):
        return False

    if not isinstance(message.signal_quality, float) or not (-75 <= message.signal_quality <= -25):
        return False

    signal_params = generate_random_signal_parameters()

    # Validate signal parameters based on cell type and location
    if 'urban' in scenario_cell_type:
        if signal_params['rssi'] < -75 or signal_params['ecno'] < 8 or signal_params['ci'] < -4:
            return False

    elif 'suburban' in scenario_cell_type:
        if signal_params['rssi'] < -85 or signal_params['ecno'] < 10 or signal_params['ci'] < 0:
            return False

    elif 'rural' in scenario_cell_type:
        if signal_params['rssi'] < -95 or signal_params['ecno'] < 12 or signal_params['ci'] < 5:
            return False

    return True

def create_messages(num_structures, scenario_cell_type):
    messages = []

    for _ in range(num_structures):
        cell_id = random.randint(1, 1000)
        bcch_n_radio_network = random.randint(1, 99)
        tx_status = random.choice([0, 1])
        signal_quality = round(random.uniform(-75.0, -25.0), 2)

        rssi, ecno, ci = generate_random_signal_parameters().values()

        message = DTL_CDMA_MESSAGE_T(cell_id, bcch_n_radio_network, tx_status, signal_quality, rssi, ecno, ci)

        if validate_message(message, scenario_cell_type):
            messages.append(message)

    return messages

def main():
    num_structures = int(input(""Enter the number of structures to generate: ""))
    scenario_cell_type = input(""Enter cell type (urban/suburban/rural): "").lower()

    messages = create_messages(num_structures, scenario_cell_type)

    for msg in messages:
        print(f""Cell ID: {msg.cell_id}, BCCH/Radio Network: {msg.bcch_n_radio_network}, ""
              f""Tx Status: {msg.tx_status}, Signal Quality: {msg.signal_quality}, ""
              f""RSSI: {msg.rssi:.2f}, ECNO: {msg.ecno:.2f}, C/I: {msg.ci:.2f}"")

if __name__ == ""__main__"":
    main()
