# Consistent Hashing implementation for load balancing
class ConsistentHash:
    def __init__(self, nodes=None):
        self.nodes = set(nodes) if nodes else set()
        self.ring = dict()

    def add_node(self, node_id):
        self.nodes.add(node_id)
        hash_val = int(hashlib.md5(node_id.encode()).hexdigest(), 16)
        self.ring[hash_val] = node_id

    def remove_node(self, node_id):
        if node_id in self.nodes:
            self.nodes.remove(node_id)
            hash_val = int(hashlib.md5(node_id.encode()).hexdigest(), 16)
            del self.ring[hash_val]

    def get_node(self, key):
        if not self.nodes:
            return None
        hash_val = int(hashlib.md5(key.encode()).hexdigest(), 16)
        sorted_keys = sorted(self.ring.keys())
        for node_key in sorted_keys:
            if hash_val <= node_key:
                return self.ring[node_key]
        return self.ring[sorted_keys[0]]

# In-memory caching with bloom filters
class BloomFilter:
    def __init__(self, size=1000):
        self.size = size
        self.bit_array = [0] * size

    def add(self, item):
        index = int(hashlib.sha256(item.encode()).hexdigest(), 16) % self.size
        self.bit_array[index] = 1

    def check(self, item):
        index = int(hashlib.sha256(item.encode()).hexdigest(), 16) % self.size
        return self.bit_array[index] == 1

# User DAO for password management and validation
class UserDAO:
    users_db = {}

    @staticmethod
    def validate_password_strength(password):
        if len(password) < 8 or not any(char.isdigit() for char in password):
            raise ValueError(""Password must be at least 8 characters long with a number"")

    @staticmethod
    def create_user(username, password):
        UserDAO.validate_password_strength(password)
        hashed_pwd = generate_password_hash(password)
        UserDAO.users_db[username] = {
            'password': hashed_pwd,
            'version': 1  # Optimistic concurrency control versioning
        }

    @staticmethod
    def update_password(username, old_password, new_password):
        user = UserDAO.users_db.get(username)
        if not user or not check_password_hash(user['password'], old_password):
            raise ValueError(""Invalid username or password"")
        UserDAO.validate_password_strength(new_password)
        hashed_pwd = generate_password_hash(new_password)
        current_version = user['version']
        new_user_data = {
            'password': hashed_pwd,
            'version': current_version + 1
        }
        # Optimistic concurrency control check before updating
        if UserDAO.users_db.get(username, {}).get('version') == current_version:
            UserDAO.users_db[username] = new_user_data

    @staticmethod
    def authenticate_user(username, password):
        user = UserDAO.users_db.get(username)
        return user and check_password_hash(user['password'], password)

