from Crypto.Cipher import AES
from Crypto.Protocol.KDF import PBKDF2
from Crypto.Util.Padding import unpad
import binascii

class EnhancedAESDecryption:
    def __init__(self, password: str):
        self.salt = b'somesalt'  # Should be a fixed byte string for this example
        self.key = self.derive_key(password)

    def derive_key(self, password: str) -> bytes:
        return PBKDF2(password, self.salt, dkLen=32)

    def decrypt(self, ciphertext, mode='CBC', padding=True):
        if isinstance(ciphertext, str):
            try:
                ciphertext = binascii.unhexlify(ciphertext)
            except (TypeError, binascii.Error):
                raise ValueError(""Invalid hexadecimal string."")

        if mode == 'CBC':
            cipher = AES.new(self.key, AES.MODE_CBC, iv=ciphertext[:16])
            plaintext = unpad(cipher.decrypt(ciphertext[16:]), AES.block_size) if padding else cipher.decrypt(ciphertext[16:])
        elif mode == 'ECB':
            cipher = AES.new(self.key, AES.MODE_ECB)
            plaintext = unpad(cipher.decrypt(ciphertext), AES.block_size) if padding else cipher.decrypt(ciphertext)
        else:
            raise ValueError(""Unsupported encryption mode."")

        return plaintext

    def decrypt_with_padding_handling(self, ciphertext, mode='CBC'):
        try:
            return self.decrypt(ciphertext, mode=mode)
        except (ValueError, KeyError):
            # Handle potential padding issues
            return None
