    response.data = f""An error occurred: {e.description}""
    response.content_type = 'text/plain'
    return response

if __name__ == '__main__':
    parser = argparse.ArgumentParser(description='Run a Flask API server.')
    parser.add_argument('--port', type=int, default=5000, help='Port number to run the server on')
    parser.add_argument('--ssl', action='store_true', help='Enable SSL encryption')

    args = parser.parse_args()

    try:
        port = args.port
        if not (1 <= port <= 65535):
            raise ValueError(""Invalid port number. Port must be between 1 and 65535."")

        ssl_context = None
        if args.ssl:
            try:
                ssl_context = ('path/to/cert.pem', 'path/to/key.pem')
            except Exception as e:
                raise RuntimeError(f""Failed to load SSL certificates: {e}"")

        app.run(port=port, ssl_context=ssl_context)

    except ValueError as ve:
        print(ve)
    except RuntimeError as re:
        print(re)
