# Distributed Key-Value Storage System

from flask import Flask, request, jsonify
import hashlib
import hmac
import secrets
from collections import defaultdict
from threading import Lock
from cachetools import LRUCache, BloomFilter
import logging
import os

app = Flask(__name__)

# Configuration and Initialization
class Config:
    SECRET_KEY = secrets.token_hex(16)
    CACHE_SIZE = 1000
    BLOOM_FILTER_CAPACITY = 10000
    LOG_FILE = 'storage_system.log'

config = Config()

logging.basicConfig(filename=config.LOG_FILE, level=logging.INFO)

# User Authentication and Access Control
users = {}
user_lock = Lock()

def authenticate(username, password):
    with user_lock:
        if username in users and hmac.compare_digest(hmac.new(users[username]['salt'].encode(), password.encode(), hashlib.sha256).hexdigest(), users[username]['hash']):
            return True
    return False

@app.route('/register', methods=['POST'])
def register():
    data = request.json
    username, password = data['username'], data['password']

    # Password strength validation (example)
    if len(password) < 8 or not any(char.isdigit() for char in password):
        return jsonify({'error': 'Password too weak'}), 400

    with user_lock:
        if username in users:
            return jsonify({'error': 'Username already exists'}), 409
        salt = secrets.token_hex(16)
        hash_pwd = hmac.new(salt.encode(), password.encode(), hashlib.sha256).hexdigest()
        users[username] = {'salt': salt, 'hash': hash_pwd}

    return jsonify({'message': 'User registered successfully'}), 201

@app.route('/login', methods=['POST'])
def login():
    data = request.json
    username, password = data['username'], data['password']

    if authenticate(username, password):
        token = secrets.token_hex(16)
        return jsonify({'token': token})
    else:
        return jsonify({'error': 'Invalid credentials'}), 401

# Consistent Hashing for Load Balancing
class ConsistentHashRing:
    def __init__(self, nodes=None):
        self.nodes = set(nodes or [])
        self.ring = defaultdict(list)
        self.lock = Lock()

    def add_node(self, node_id):
        with self.lock:
            self.nodes.add(node_id)
            # Rebalance ring

    def remove_node(self, node_id):
        with self.lock:
            self.nodes.remove(node_id)
            # Rebalance ring

    def get_node(self, key):
        hash_key = int(hashlib.md5(key.encode()).hexdigest(), 16)
        return min(self.ring.keys(), key=lambda k: (k - hash_key) % (2**32))

# In-memory Caching with Bloom Filters
cache = LRUCache(maxsize=config.CACHE_SIZE)
bloom_filter = BloomFilter(capacity=config.BLOOM_FILTER_CAPACITY)

def get_value(key):
    if key in bloom_filter:
        return cache.get(key)
    return None

def set_value(key, value):
    bloom_filter.add(key)
    cache[key] = value

# Optimistic Concurrency Control
class VersionedStore:
    def __init__(self):
        self.store = {}
        self.versions = defaultdict(int)

    def get(self, key):
        return self.store.get(key), self.versions.get(key)

    def set(self, key, value, version):
        if version == self.versions[key]:
            self.store[key] = value
            self.versions[key] += 1
            return True
        return False

store = VersionedStore()

@app.route('/key/<key>', methods=['GET', 'PUT'])
def handle_key(key):
    if request.method == 'GET':
        value, version = store.get(key)
        if value is not None:
            return jsonify({'value': value, 'version': version})
        else:
            return jsonify({'error': 'Key not found'}), 404

    elif request.method == 'PUT':
        data = request.json
        value = data['value']
        version = data.get('version', 0)

        if store.set(key, value, version):
            return jsonify({'message': 'Value updated successfully'})
        else:
            return jsonify({'error': 'Version mismatch'}), 409

# Error Handling and Logging
@app.errorhandler(500)
def handle_500_error(error):
    logging.error(f""Internal Server Error: {str(error)}"")
    return jsonify({'error': 'Internal server error'}), 500

# Monitoring Tools (Example using Prometheus client)
from prometheus_client import start_http_server, Counter

requests_counter = Counter('http_requests_total', 'Total HTTP Requests')

@app.before_request
def before_request():
    requests_counter.inc()

if __name__ == '__main__':
    start_http_server(8000)  # Start Prometheus metrics server on port 8000
    app.run(debug=True)

