from flask import Flask, request, jsonify

app = Flask(__name__)

# Dummy database for demonstration purposes
users_db = {
    'user1': {'name': 'Alice', 'email': 'alice@example.com'},
    'user2': {'name': 'Bob', 'email': 'bob@example.com'}
}

@app.route('/api/user/<user_id>', methods=['PATCH'])
def update_user(user_id):
    if user_id not in users_db:
        return jsonify({'error': 'User not found'}), 404

    # Get the fields to be updated from the request body
    updates = request.get_json()

    # Update the existing user profile with new values
    for key, value in updates.items():
        if key in users_db[user_id]:
            users_db[user_id][key] = value

    return jsonify(users_db[user_id]), 200

@app.route('/api/user/<user_id>', methods=['DELETE'])
def delete_user(user_id):
    if user_id not in users_db:
        return jsonify({'error': 'User not found'}), 404

    # Remove the user from the database
    del users_db[user_id]

    return jsonify({'message': f'User {user_id} deleted successfully'}), 200


if __name__ == '__main__':
    app.run(debug=True)
