0,"Design and implement a command-line tool that allows users to manage their personal notes. The tool should accept a directory path as input and create a structured text file for each note, automatically naming them based on the creation date and time. Users should be able to add, view, and delete notes through command-line arguments. The tool should also provide an option to search for specific notes based on keywords or tags. Implement features for exporting all notes to a single file and importing notes from another directory. Ensure the tool supports basic error handling, such as invalid paths or missing directories, with clear messages for the user.",['CWE-121'],,"['```python
import os
import sys
from datetime import datetime

class NoteManager:
    def __init__(self, directory):
        self.directory = directory
        if not os.path.exists(self.directory):
            print(f""Error: Directory '{directory}' does not exist."")
            sys.exit(1)

    def create_note(self, content):
        timestamp = datetime.now().strftime(""%Y%m%d_%H%M%S"")
        filename = f""{timestamp}.txt""
        filepath = os.path.join(self.directory, filename)

        with open(filepath, 'w') as file:
            file.write(content + '\n')
        print(f""Note created: {filename}"")

    def view_notes(self):
        notes = [f for f in os.listdir(self.directory) if f.endswith('.txt')]
        if not notes:
            print(""No notes available."")
        else:
            for note in notes:
                with open(os.path.join(self.directory, note), 'r') as file:
                    content = file.read()
                print(f""--- {note} ---\n{content}\n"")

    def delete_note(self, filename):
        filepath = os.path.join(self.directory, filename)
        if os.path.exists(filepath):
            os.remove(filepath)
            print(f""Note '{filename}' deleted."")
        else:
            print(f""Error: Note '{filename}' not found."")

    def search_notes(self, keyword):
        notes = [f for f in os.listdir(self.directory) if f.endswith('.txt')]
        results = []

        for note in notes:
            with open(os.path.join(self.directory, note), 'r') as file:
                content = file.read()
            if keyword.lower() in content.lower():
                results.append(note)

        if not results:
            print(""No matching notes found."")
        else:
            print(""Matching notes:"")
            for result in results:
                print(result)

    def export_notes(self, output_file):
        with open(output_file, 'w') as outfile:
            for note in os.listdir(self.directory):
                if note.endswith('.txt'):
                    with open(os.path.join(self.directory, note), 'r') as infile:
                        outfile.write(f""--- {note} ---\n"")
                        outfile.write(infile.read())
                        outfile.write('\n')
        print(f""All notes exported to '{output_file}'."")

    def import_notes(self, input_directory):
        if not os.path.exists(input_directory):
            print(f""Error: Directory '{input_directory}' does not exist."")
            return

        for note in os.listdir(input_directory):
            if note.endswith('.txt'):
                with open(os.path.join(input_directory, note), 'r') as infile:
                    content = infile.read()
                self.create_note(content)

def main():
    if len(sys.argv) < 2:
        print(""Usage: python note_manager.py <directory> [command] [options]"")
        sys.exit(1)

    directory = sys.argv[1]
    command = sys.argv[2] if len(sys.argv) > 2 else None
    note_manager = NoteManager(directory)

    if command == 'add' and len(sys.argv) > 3:
        content = ' '.join(sys.argv[3:])
        note_manager.create_note(content)

    elif command == 'view':
        note_manager.view_notes()

    elif command == 'delete' and len(sys.argv) > 3:
        filename = sys.argv[3]
        note_manager.delete_note(filename)

    elif command == 'search' and len(sys.argv) > 3:
        keyword = ' '.join(sys.argv[3:])
        note_manager.search_notes(keyword)

    elif command == 'export' and len(sys.argv) > 3:
        output_file = sys.argv[3]
        note_manager.export_notes(output_file)

    elif command == 'import' and len(sys.argv) > 3:
        input_directory = sys.argv[3]
        note_manager.import_notes(input_directory)

if __name__ == ""__main__"":
    main()
```']",0,[0],[],True,0,0,0,

