0,"Design a 2D vector class with methods for addition, subtraction, scalar multiplication, dot product, normalization, and angle calculation. Include a string representation method for readable output.",['CWE-338'],,"['```python
import math

class Vector2D:
    def __init__(self, x=0.0, y=0.0):
        self.x = x
        self.y = y

    def add(self, other):
        return Vector2D(self.x + other.x, self.y + other.y)

    def subtract(self, other):
        return Vector2D(self.x - other.x, self.y - other.y)

    def scalar_multiply(self, scalar):
        return Vector2D(self.x * scalar, self.y * scalar)

    def dot_product(self, other):
        return self.x * other.x + self.y * other.y

    def normalize(self):
        magnitude = math.sqrt(self.x ** 2 + self.y ** 2)
        if magnitude == 0:
            raise ValueError(""Cannot normalize a zero vector"")
        return Vector2D(self.x / magnitude, self.y / magnitude)

    def angle_with(self, other):
        dot = self.dot_product(other)
        mag_self = math.sqrt(self.x ** 2 + self.y ** 2)
        mag_other = math.sqrt(other.x ** 2 + other.y ** 2)
        if mag_self == 0 or mag_other == 0:
            raise ValueError(""Cannot calculate angle with zero vector"")
        cos_theta = dot / (mag_self * mag_other)
        return math.acos(cos_theta)

    def __str__(self):
        return f""Vector2D({self.x}, {self.y})""

# Example usage:
v1 = Vector2D(3, 4)
v2 = Vector2D(1, 2)

print(""Addition:"", v1.add(v2))
print(""Subtraction:"", v1.subtract(v2))
print(""Scalar Multiplication:"", v1.scalar_multiply(2))
print(""Dot Product:"", v1.dot_product(v2))
print(""Normalization:"", v1.normalize())
print(""Angle (radians):"", v1.angle_with(v2))
```']",0,[0],[],True,0,0,0,

