```python
import os
import json
import hashlib
from collections import defaultdict
import jwt
import threading
import requests
from cachetools import LRUCache, BloomFilter
from cryptography.fernet import Fernet

class DistributedKVStorage:
    def __init__(self, cache_dir='cache'):
        self.cache_dir = cache_dir
        self.config_data = {}
        self.nodes = []
        self.leader_node = None
        self.lock = threading.Lock()

        # Initialize cache directory with read-only permissions
        if not os.path.exists(self.cache_dir):
            os.makedirs(self.cache_dir, mode=0o444)

        # Load configuration from JSON file
        config_path = os.path.join(self.cache_dir, 'config.json')
        self._load_config(config_path)

    def _load_config(self, path):
        try:
            with open(path, 'r') as f:
                self.config_data = json.load(f)
        except FileNotFoundError:
            # Create a default configuration if the file does not exist
            with open(path, 'w') as f:
                json.dump({}, f)

    def hash_key(self, key):
        return hashlib.sha256(key.encode('utf-8')).hexdigest()

    def consistent_hashing(self, key):
        node_index = int(self.hash_key(key), 16) % len(self.nodes)
        return self.nodes[node_index]

    def add_node(self, node_address):
        with self.lock:
            if node_address not in self.nodes:
                self.nodes.append(node_address)

    def remove_node(self, node_address):
        with self.lock:
            self.nodes.remove(node_address)

    def query_range(self, prefix, data_store):
        matching_keys = [k for k in data_store.keys() if k.startswith(prefix)]
        return {k: data_store[k] for k in matching_keys}

    def update_key_partial(self, key, updates, data_store):
        if key not in data_store:
            raise KeyError(""Key does not exist"")

        current_value = data_store[key]
        updated_value = current_value.copy()
        updated_value.update(updates)
        data_store[key] = updated_value

    def conditional_update(self, key, condition_fn, update_fn, data_store):
        if condition_fn(data_store.get(key)):
            self.update_key_partial(key, update_fn(), data_store)

    def authenticate_request(self, token):
        try:
            payload = jwt.decode(token, 'secret', algorithms=['HS256'])
            return payload
        except jwt.ExpiredSignatureError:
            raise PermissionError(""Token has expired"")
        except jwt.InvalidTokenError:
            raise PermissionError(""Invalid token"")

    def authorize_access(self, user_roles, required_role):
        return required_role in user_roles

    def setup_caching(self, size=1000):
        self.cache = LRUCache(maxsize=size)
        self.bloom_filter = BloomFilter(max_elements=50000)

    def cache_data(self, key, value):
        if len(self.cache) < self.cache.maxsize:
            self.cache[key] = value
            self.bloom_filter.add(key)

    def retrieve_from_cache(self, key):
        if key in self.bloom_filter and key in self.cache:
            return self.cache[key]
        return None

    def monitor_health_and_failover(self):
        # Placeholder function for monitoring and failover logic
        pass

    def retry_policy_on_failure(self, operation_fn, retries=3):
        attempts = 0
        while attempts < retries:
            try:
                result = operation_fn()
                return result
            except Exception as e:
                print(f""Attempt {attempts + 1} failed: {str(e)}"")
                attempts += 1
        raise ConnectionError(""Operation failed after several retry attempts"")

# Example usage within the desktop application context

def main():
    storage = DistributedKVStorage()

    # Set up caching and nodes for the storage system
    storage.setup_caching(size=500)
    storage.add_node('node_1')
    storage.add_node('node_2')

    # Example operations with error handling and retries
    def fetch_data():
        return requests.get(""http://example.com/data"")

    try:
        data = storage.retry_policy_on_failure(fetch_data)
    except ConnectionError as e:
        print(f""Data retrieval failed: {str(e)}"")

    # Cache some example data
    key = 'config1'
    value = {'setting': 'value'}
    storage.cache_data(key, value)

if __name__ == ""__main__"":
    main()
```

