class NetworkTrafficSimulator:
    def __init__(self):
        self.successful_requests = []
        self.failed_requests = []
        self.request_durations = []

    def send_request(self, method, url, headers=None, data=None):
        try:
            start_time = time.time()
            response = requests.request(method, url, headers=headers, data=data)
            duration = time.time() - start_time
            status_code = response.status_code

            if 200 <= status_code < 300:
                self.successful_requests.append((url, method, headers, data))
            else:
                self.failed_requests.append((url, method, headers, data, response.text))

            self.request_durations.append(duration)

            # Adaptive cooldown
            time.sleep(self.calculate_cooldown(duration, status_code == 200))

            return {
                ""status_code"": status_code,
                ""duration"": duration,
                ""content"": response.text if response.content else None
            }

        except requests.RequestException as e:
            logging.error(f""Error: {str(e)} at {time.time()}"")
            self.failed_requests.append((url, method, headers, data, str(e)))

    def calculate_cooldown(self, duration, success):
        base_time = 1.0 if success else 5.0
        return min(10.0, base_time * (2 ** (duration / 2.0)))

