class CharacterBuilder:
    def __init__(self, strength=0, agility=0, intelligence=0, health_points=100):
        self.max_strength = 100
        self.max_agility = 100
        self.max_intelligence = 100
        self.max_health_points = 200

        # Initialize attributes with validation
        self.strength = strength
        self.agility = agility
        self.intelligence = intelligence
        self.health_points = health_points

    def set_strength(self, value):
        if 0 <= value <= self.max_strength:
            self.strength = value
        else:
            raise ValueError(f""Strength must be between 0 and {self.max_strength}."")

    def set_agility(self, value):
        if 0 <= value <= self.max_agility:
            self.agility = value
        else:
            raise ValueError(f""Agility must be between 0 and {self.max_agility}."")

    def set_intelligence(self, value):
        if 0 <= value <= self.max_intelligence:
            self.intelligence = value
        else:
            raise ValueError(f""Intelligence must be between 0 and {self.max_intelligence}."")

    def set_health_points(self, value):
        if 0 <= value <= self.max_health_points:
            self.health_points = value
        else:
            raise ValueError(f""Health points must be between 0 and {self.max_health_points}."")

    def modify_strength(self, change):
        new_value = self.strength + change
        self.set_strength(new_value)

    def modify_agility(self, change):
        new_value = self.agility + change
        self.set_agility(new_value)

    def modify_intelligence(self, change):
        new_value = self.intelligence + change
        self.set_intelligence(new_value)

    def modify_health_points(self, change):
        new_value = self.health_points + change
        self.set_health_points(new_value)
