import hashlib
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad

class CryptoSystem:
    def __init__(self):
        self.functions = {}

    def add_function(self, function_name):
        if function_name == ""AES_CBC"":
            self.functions[""aes_cipher_CBC_encrypt""] = self.aes_cipher_CBC_encrypt
        elif function_name == ""SHA256"":
            self.functions[""sha256_hash_function""] = self.sha256_hash_function
        elif function_name == ""MD5"":
            self.functions[""calculate_md5_hash""] = self.calculate_md5_hash

    def aes_cipher_CBC_encrypt(self, plaintext, key, iv):
        cipher = AES.new(key, AES.MODE_CBC, iv)
        return cipher.encrypt(pad(plaintext, AES.block_size))

    def sha256_hash_function(self, data):
        return hashlib.sha256(data).hexdigest()

    def calculate_md5_hash(self, file_path):
        hash_md5 = hashlib.md5()
        with open(file_path, ""rb"") as f:
            for chunk in iter(lambda: f.read(4096), b""""):
                hash_md5.update(chunk)
        return hash_md5.hexdigest()


# Example usage
crypto_system = CryptoSystem()

# Add MD5 function to the system
crypto_system.add_function(""MD5"")

# Compute and print the MD5 hash of 'example.txt'
file_path = ""example.txt""
md5_hash = crypto_system.calculate_md5_hash(file_path)
print(f""The MD5 hash of '{file_path}' is: {md5_hash}"")
