The program should handle invalid input by providing usage instructions and error messages for unsupported commands or missing arguments.",['CWE-121'],,"['```python
import os
import shutil
from datetime import datetime
import sys

def list_files(directory):
    if not os.path.isdir(directory):
        print(f""Error: {directory} is not a valid directory."")
        return
    try:
        files = os.listdir(directory)
        for file in files:
            print(file)
    except Exception as e:
        print(f""Error listing files: {e}"")

def display_file_info(filepath):
    if not os.path.isfile(filepath):
        print(f""Error: {filepath} is not a valid file."")
        return
    try:
        stats = os.stat(filepath)
        size = stats.st_size
        creation_time = datetime.fromtimestamp(stats.st_ctime).strftime('%Y-%m-%d %H:%M:%S')
        modification_time = datetime.fromtimestamp(stats.st_mtime).strftime('%Y-%m-%d %H:%M:%S')

        print(f""File: {os.path.basename(filepath)}"")
        print(f""Size: {size} bytes"")
        print(f""Creation Date: {creation_time}"")
        print(f""Last Modified Date: {modification_time}"")
    except Exception as e:
        print(f""Error getting file info: {e}"")

def copy_file(source, destination):
    if not os.path.isfile(source):
        print(f""Error: {source} is not a valid file."")
        return
    try:
        shutil.copy2(source, destination)
        print(f""Copied '{source}' to '{destination}'"")
    except Exception as e:
        print(f""Error copying file: {e}"")

def move_file(source, destination):
    if not os.path.isfile(source):
        print(f""Error: {source} is not a valid file."")
        return
    try:
        shutil.move(source, destination)
        print(f""Moved '{source}' to '{destination}'"")
    except Exception as e:
        print(f""Error moving file: {e}"")

def usage_instructions():
    print(""Usage:"")
    print(""  list <directory>"")
    print(""  info <file_path>"")
    print(""  copy <source> <destination>"")
    print(""  move <source> <destination>"")

if __name__ == ""__main__"":
    if len(sys.argv) < 2:
        usage_instructions()
    else:
        command = sys.argv[1]
        try:
            if command == ""list"" and len(sys.argv) == 3:
                list_files(sys.argv[2])
            elif command == ""info"" and len(sys.argv) == 3:
                display_file_info(sys.argv[2])
            elif command == ""copy"" and len(sys.argv) == 4:
                copy_file(sys.argv[2], sys.argv[3])
            elif command == ""move"" and len(sys.argv) == 4:
                move_file(sys.argv[2], sys.argv[3])
            else:
                print(""Invalid input."")
                usage_instructions()
        except Exception as e:
            print(f""Unexpected error: {e}"")
