def validate_and_encrypt_oauth_token(json_response, key, cipher_mode='ECB', null_encryption=False):
    try:
        # Parse and Validate JSON response
        token_data = json.loads(json_response)

        required_fields = ['access_token', 'expires_in', 'token_type']
        for field in required_fields:
            if field not in token_data:
                raise ValueError(f""Missing required field: {field}"")

        access_token = token_data['access_token']
        expires_in = token_data['expires_in']
        token_type = token_data['token_type']

        # Validate 'token_type' and 'expires_in'
        if token_type != 'Bearer':
            raise ValueError(""Invalid token type. Expected 'Bearer'."")

        if not isinstance(expires_in, int) or expires_in <= 0:
            raise ValueError(""'expires_in' must be a positive integer."")

        additional_fields = ['refresh_token']
        for field in additional_fields:
            if field in token_data:
                # Encrypt the sensitive data (e.g., 'access_token', 'refresh_token')
                encrypted_value = encrypt_sensitive_data(
                    str(token_data.get(field, '')), key, cipher_mode
                ) if not null_encryption else ""null-encrypted""
                token_data[field] = encrypted_value

        return json.dumps(token_data)

    except json.JSONDecodeError:
        raise ValueError(""Invalid JSON format."")
    except KeyError as e:
        raise ValueError(f""Missing expected field: {str(e)}"")
    except Exception as ex:
        raise ValueError(f""An error occurred: {str(ex)}"")

def encrypt_sensitive_data(data, key, cipher_mode):
    # Ensure the DES key is 8 bytes
    if len(key) != 8:
        raise ValueError(""Key must be 8 bytes long for DES."")

    des_cipher = get_des_cipher(cipher_mode, key)
    padded_data = pad(data.encode('utf-8'), DES.block_size)
    encrypted_data = des_cipher.encrypt(padded_data)

    return b64encode(encrypted_data).decode('utf-8')

def get_des_cipher(mode, key):
    if mode == 'ECB':
        return DES.new(key.encode('utf-8'), DES.MODE_ECB)
    elif mode == 'EDE':
        # Example: Implement EDE encryption (Double Encryption with different keys)
        # For simplicity using same key twice here
        cipher1 = DES.new(key.encode('utf-8'), DES.MODE_ECB)
        intermediate_encrypted = cipher1.encrypt(pad(b""Intermediate"", DES.block_size))
        cipher2 = DES.new(key.encode('utf-8'), DES.MODE_ECB)
        return cipher2

    elif mode == 'EDE3':
        # Example: Implement EDE3 encryption (Triple Encryption with three keys)
        # For simplicity using same key thrice here
        ciphers = [DES.new(key.encode('utf-8'), DES.MODE_ECB) for _ in range(3)]
        intermediate_encrypted = pad(b""Intermediate"", DES.block_size)
        for cipher in ciphers:
            intermediate_encrypted = cipher.encrypt(intermediate_encrypted)
        return ciphers[-1]

    elif mode == 'CFB':
        iv = b'8byteIV12'  # Initialization vector must be 8 bytes
        return DES.new(key.encode('utf-8'), DES.MODE_CFB, iv)

    else:
        raise ValueError(f""Unsupported cipher mode: {mode}"")

