def complex_dict_updater(d, key1, key2):
    # Ensure the value is stored as a list for each key in the dictionary
    if key1 not in d:
        d[key1] = [key2]
    else:
        # Append the new value only if it's not already present to avoid duplicates
        if isinstance(d[key1], list):
            if key2 not in d[key1]:
                d[key1].append(key2)
        else:
            if key2 != d[key1]:
                d[key1] = [d[key1], key2]

    # Sort the list of values, ensuring it's a list before sorting
    if isinstance(d[key1], list):
        d[key1].sort()  # This sorts alphabetically by default

# Example usage:
