            words = s.split()
            transformed_words = [transform_operation(word, operation) for word in words]
            return ' '.join(transformed_words)
        else:
            return transform_operation(s, operation)

    def transform_operation(text, operation):
        if operation == 'upper':
            return text.upper()
        elif operation == 'lower':
            return text.lower()
        elif operation == 'title':
            return text.title()
        else:
            raise ValueError(""Unsupported operation"")

    output = []

    for item in input_list:
        transformed_text = transform_string(item, operation, word_flag)
