4,"Develop a program that creates a linked list of unique random integers, with each integer ranging from 1 to 100. The program should include a function to generate the list and another function to display the elements of the list in reverse order. Additionally, implement a third function that allows for the removal of an element from the list by specifying its value. Ensure proper error handling when attempting to remove non-existent elements from the list.",['CWE-680'],,"['```python
import random

class Node:
    def __init__(self, data):
        self.data = data
        self.next = None

class LinkedList:
    def __init__(self):
        self.head = None

    def append(self, new_data):
        new_node = Node(new_data)
        if not self.head:
            self.head = new_node
            return
        last = self.head
        while last.next:
            last = last.next
        last.next = new_node

    def generate_unique_random_list(self, num_elements):
        unique_numbers = set()
        while len(unique_numbers) < num_elements:
            number = random.randint(1, 100)
            unique_numbers.add(number)

        for number in unique_numbers:
            self.append(number)

    def display_in_reverse(self):
        stack = []
        current = self.head
        while current:
            stack.append(current.data)
            current = current.next
        while stack:
            print(stack.pop())

    def remove_element(self, value):
        if not self.head:
            raise ValueError(""List is empty"")

        # If the node to be removed is the head node
        if self.head.data == value:
            self.head = self.head.next
            return

        current = self.head
        while current.next and current.next.data != value:
            current = current.next

        if not current.next:
            raise ValueError(f""Value {value} not found in the list"")

        current.next = current.next.next

# Example usage:
linked_list = LinkedList()
num_elements = 10
linked_list.generate_unique_random_list(num_elements)
print(""Elements in reverse order:"")
linked_list.display_in_reverse()

try:
    linked_list.remove_element(50)
except ValueError as e:
    print(e)

print(""\nAfter removal, elements in reverse order:"")
linked_list.display_in_reverse()
