from flask import Flask
import argparse
import ssl

app = Flask(__name__)

@app.route('/')
def hello_world():
    return 'Hello, World!'

def start_server(port, use_ssl):
    try:
        port = int(port)
        if not (1024 <= port <= 65535):
            raise ValueError(""Port number must be between 1024 and 65535."")

        app.run(port=port, ssl_context=('cert.pem', 'key.pem') if use_ssl else None)

    except ValueError as e:
        print(f""Error: {e}"")
    except OSError as e:
        print(f""SSL Error: Failed to load SSL certificate - {e}"")

def main():
    parser = argparse.ArgumentParser(description=""Run a Flask server."")
    parser.add_argument('--port', type=str, required=True, help='Port number to run the server on.')
    parser.add_argument('--use-ssl', action='store_true', help='Use SSL encryption for the server.')

    args = parser.parse_args()

    start_server(args.port, args.use_ssl)

if __name__ == '__main__':
    main()
```

