import random

class Node:
    def __init__(self, data):
        self.data = data
        self.prev = None
        self.next = None

class DoublyLinkedList:
    def __init__(self):
        self.head = None

    def generateList(self):
        if not self.head:
            for _ in range(random.randint(1, 10)):  # Generate between 1 to 10 unique random numbers
                value = random.randint(1, 100)
                self.insertNode(value)

    def displayReverse(self):
        current = self.tail()
        while current:
            print(current.data, end="" "")
            current = current.prev
        print()

    def insertNode(self, value):
        if self.findNode(value):
            raise ValueError(f""Value {value} already exists in the list."")

        new_node = Node(value)
        if not self.head:
            self.head = new_node
        else:
            current = self.head
            while current.next:
                current = current.next

            current.next = new_node
            new_node.prev = current

    def removeNode(self, value):
        if not self.findNode(value):
            return False

        current = self.head
        while current and current.data != value:
            current = current.next

        if current is None:  # Node not found
            return False

        if current.prev:
            current.prev.next = current.next
        else:
            self.head = current.next

        if current.next:
            current.next.prev = current.prev
        else:
            # If we're removing the last node, set tail to prev
            self.tail_node = current.prev

        return True

    def findNode(self, value):
        current = self.head
        while current:
            if current.data == value:
                return True
            current = current.next
        return False

    def clearList(self):
        self.head = None
        self.tail_node = None  # Reset the tail node reference

    def tail(self):
        current = self.head
        while current and current.next:
            current = current.next
        return current

# Usage example (for testing purposes)
if __name__ == ""__main__"":
    dll = DoublyLinkedList()
    dll.generateList()

    print(""Original List in reverse:"")
    dll.displayReverse()

    try:
        dll.insertNode(50)  # Attempt to insert a new unique value
    except ValueError as e:
        print(e)

    if dll.removeNode(5):  # Try removing an existing node
        print(f""Removed 5 from the list."")
    else:
        print(""Value not found for removal."")

    print(""List after operations in reverse:"")
    dll.displayReverse()

    dll.clearList()
    print(""Cleared List in reverse (should be empty):"")
    dll.displayReverse()
