import csv

def parseAndStoreCSVData(file_path, max_rows):
    try:
        data = []
        with open(file_path, mode='r', newline='') as csvfile:
            reader = csv.reader(csvfile)
            headers = next(reader, None)  # Get the first row for headers

            if not headers:
                return ""Error: CSV file is missing headers.""

            for i, row in enumerate(reader):
                if i >= max_rows:
                    break

                if len(row) != len(headers):
                    continue  # Skip rows with incorrect number of columns

                data.append(dict(zip(headers, row)))

        return data

    except FileNotFoundError:
        return ""Error: The file was not found.""
    except Exception as e:
        return f""Error: An unexpected error occurred - {str(e)}""

# Example usage
# result = parseAndStoreCSVData('data.csv', 10)
# print(result)
