# Python Script: Network Traffic Simulator with Adaptive Cooldown

import requests
import time
from threading import Thread
import logging
import os
from flask import Flask, jsonify

logging.basicConfig(filename='network_traffic.log', level=logging.DEBUG)

class NetworkSimulator:
    def __init__(self):
        self.requests_log = {'success': [], 'failed': []}
        self.monitor_thread = Thread(target=self.monitor_logs)
        self.api_app = Flask(__name__)

        @self.api_app.route('/stats', methods=['GET'])
        def get_stats():
            stats = {
                'total_requests': len(self.requests_log['success']) + len(self.requests_log['failed']),
                'successful_requests': len(self.requests_log['success']),
                'failed_requests': len(self.requests_log['failed']),
                'average_response_time': self.calculate_average_response_time()
            }
            return jsonify(stats)

    def send_request(self, method, url, headers=None, data=None):
        try:
            start_time = time.time()
            response = requests.request(method, url, headers=headers, json=data)
            duration = time.time() - start_time
            self.log_request(response.status_code, duration, success=response.ok)

            if not response.ok:
                logging.error(f""Request failed: {response.text}"")

        except requests.RequestException as e:
            logging.error(f""Error during request: {str(e)}"")

        cooldown = self.adaptive_cooldown()
        time.sleep(cooldown)

    def log_request(self, status_code, duration, success):
        entry = {
            'status_code': status_code,
            'duration': duration
        }
        if success:
            self.requests_log['success'].append(entry)
        else:
            self.requests_log['failed'].append(entry)

    def adaptive_cooldown(self):
        # Basic adaptive cooldown mechanism (can be improved based on error rate, etc.)
        return min(2, 5 - len(self.requests_log['failed']) / 10)

    def calculate_average_response_time(self):
        total_time = sum(log['duration'] for log in self.requests_log['success'])
        count = len(self.requests_log['success'])
        return total_time / count if count > 0 else 0

    def monitor_logs(self):
        while True:
            # Monitor and handle logs (e.g., send notifications)
            time.sleep(60)

def start_flask_app():
    app = NetworkSimulator()
    Thread(target=lambda: app.api_app.run(port=5000)).start()

# Start the Flask application in a separate thread
start_flask_app()
