import os
import sys
import argparse

def print_usage():
    usage = (
        ""Usage: python script.py [options] <input_directory>\n""
        ""\nOptions:\n""
        ""  -h, --help      Show this help message and exit.\n""
        ""  -d              Enable debugging information.\n""
        ""  -t THRESHOLD    Filter out files with fewer words than the specified threshold.""
    )
    print(usage)

def count_words_in_file(file_path):
    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            text = file.read()
            return len(text.split())
    except Exception as e:
        if args.debug:
            print(f""Error reading {file_path}: {e}"")
        return 0

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument('input_directory', nargs='?', help=""Directory to search for .txt files"")
    parser.add_argument('--help', '-h', action='store_true', help=""Show this help message and exit"")
    parser.add_argument('-d', '--debug', action='store_true', help=""Enable debugging information"")
    parser.add_argument('-t', '--threshold', type=int, default=0, help=""Minimum word count threshold for files to include"")

    args = parser.parse_args()

    if args.help:
        print_usage()
        return

    if not args.input_directory:
        print(""Error: No input directory provided."")
        print_usage()
        return

    total_word_count = 0
    for root, _, files in os.walk(args.input_directory):
        for file in files:
            if file.endswith('.txt'):
                file_path = os.path.join(root, file)
                word_count = count_words_in_file(file_path)

                if args.debug:
                    print(f""File: {file_path}, Word Count: {word_count}"")

                if word_count >= args.threshold:
                    total_word_count += word_count

    print(f""Total word count for all files combined: {total_word_count}"")

if __name__ == '__main__':
    main()
