import os
import sys
import logging
from concurrent.futures import ProcessPoolExecutor, as_completed
from pathlib import Path
from tqdm import tqdm
import argparse
import re

def parse_args():
    parser = argparse.ArgumentParser(description='Enhanced Word Counter Script')

    parser.add_argument('input_dir', help='Directory to scan for .txt files')
    parser.add_argument('-o', '--output', type=str, help='Output file path')
    parser.add_argument('--min-length', type=int, default=1, help='Minimum word length filter')
    parser.add_argument('--consider-punctuation', action='store_true', help='Consider punctuation as separate words')
    parser.add_argument('--depth', type=int, default=float('inf'), help='Depth of recursion')

    logging_group = parser.add_mutually_exclusive_group()
    logging_group.add_argument('--log-file', type=str, help='Log file path')
    logging_group.add_argument('--log-level', choices=['DEBUG', 'INFO', 'WARNING', 'ERROR'], help='Set the log level')

    return parser.parse_args()

def setup_logging(log_file=None, log_level=None):
    if log_file:
        logging.basicConfig(filename=log_file, level=getattr(logging, log_level.upper(), None), 
                            format='%(asctime)s - %(levelname)s - %(message)s')
    else:
        logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def count_words(file_path, min_length, consider_punctuation):
    try:
        with open(file_path, 'r') as file:
            content = file.read()
            if not consider_punctuation:
                words = re.findall(r'\b\w+\b', content)
            else:
                words = re.findall(r'\S+', content)
            return sum(1 for word in words if len(word) >= min_length)
    except Exception as e:
        logging.error(f""Error reading file {file_path}: {e}"")
        return 0

def scan_directory(dir_path, depth, min_length, consider_punctuation):
    total_word_counts = []

    with ProcessPoolExecutor() as executor:
        futures = []

        for root, _, files in os.walk(dir_path):
            if len(Path(root).relative_to(dir_path).parts) > depth:
                continue

            for file in tqdm(files, desc=""Scanning files""):
                if file.endswith('.txt'):
                    full_path = os.path.join(root, file)
                    futures.append(executor.submit(count_words, full_path, min_length, consider_punctuation))

        for future in as_completed(futures):
            result = future.result()
            total_word_counts.append(result)

    return total_word_counts

def main():
    args = parse_args()
    setup_logging(args.log_file, args.log_level)

    if not os.path.exists(args.input_dir) or not os.path.isdir(args.input_dir):
        logging.error(""Input directory does not exist or is not accessible."")
        sys.exit(1)

    word_counts = scan_directory(args.input_dir, args.depth, args.min_length, args.consider_punctuation)

    if args.output:
        with open(args.output, 'w') as output_file:
            for count in word_counts:
                output_file.write(f""{count}\n"")
    else:
        print(""\n"".join(map(str, word_counts)))

if __name__ == '__main__':
    main()
```

