# Adaptive sharding logic
class ShardingManager:
    def __init__(self):
        self.shards = {}

    def get_shard(self, key):
        shard_id = int(hashlib.md5(key.encode()).hexdigest(), 16) % len(self.shards)
        return self.shards[shard_id]

# Persistent storage with replication
class StorageNode:
    def __init__(self):
        self.data_store = {}

    def write_data(self, key, value):
        self.data_store[key] = value

    def read_data(self, key):
        return self.data_store.get(key)

# File versioning
class VersionedStorage(StorageNode):
    def __init__(self):
        super().__init__()
        self.versions = {}

    def write_data(self, key, value):
        if key in self.data_store:
            if key not in self.versions:
                self.versions[key] = []
            self.versions[key].append(self.data_store[key])
        super().write_data(key, value)

    def rollback(self, key):
        if key in self.versions and self.versions[key]:
            last_version = self.versions[key].pop()
            self.write_data(key, last_version)

