import random
import time

class RandomStringRemover:
    def __init__(self):
        self.last_invoked = None

    def remove_random_string(self, strings_list):
        if self.last_invoked is not None and (time.time() - self.last_invoked) < 7:
            raise Exception(""Function can only be invoked every 7 seconds."")

        if not strings_list:
            return None

        removed_string = random.choice(strings_list)
        strings_list.remove(removed_string)
        self.last_invoked = time.time()

        return removed_string

# Usage example
