# network_simulation.py

import requests
import time
from threading import Thread
import smtplib
from email.message import EmailMessage
from flask import Flask, jsonify

app = Flask(__name__)

class NetworkSimulator:
    def __init__(self):
        self.requests_log = {'success': [], 'error': []}

    def send_request(self, url, headers=None, payload=None, timeout=10):
        try:
            response = requests.get(url, headers=headers, json=payload, timeout=timeout)
            if response.status_code == 200:
                self.track_request('success', response.url, response.elapsed.total_seconds())
            else:
                self.track_request('error', response.url, str(response.text))
        except (requests.exceptions.RequestException, requests.exceptions.Timeout) as e:
            self.track_request('error', url, str(e))

    def track_request(self, status, url, details):
        entry = {'url': url, 'details': details}
        if status == 'success':
            self.requests_log['success'].append(entry)
        else:
            self.requests_log['error'].append(entry)

    def monitor_files_and_notify(self, interval=60, threshold=10):
        while True:
            time.sleep(interval)
            # Example condition: Notify if more than threshold errors in the last minute
            if len(self.requests_log['error']) > threshold:
                self.notify_user('High error rate detected!')

    def notify_user(self, message):
