        email['From'] = 'your_email@example.com'
        email['To'] = 'recipient_email@example.com'

        with smtplib.SMTP('smtp.example.com') as server:
            server.login('user', 'password')
            server.send_message(email)

    def get_statistics(self):
        total_requests = len(self.requests_log['success']) + len(self.requests_log['error'])
        success_count = len(self.requests_log['success'])
        failure_count = len(self.requests_log['error'])

        avg_response_time = (sum([req['details'] for req in self.requests_log['success']]) / 
                             success_count) if success_count else 0

        return {
            'total_requests': total_requests,
            'successful_requests': success_count,
            'failed_requests': failure_count,
            'average_response_time': avg_response_time
        }

