        return (self.ue_id, self.mei, self.cell_id) == (other.ue_id, other.mei, other.cell_id)

def generate_unique_rndv_info_list(k: int) -> List[RNDV_INFO_T]:
    unique_combinations = set()

    while len(unique_combinations) < k:
        ue_id = random.randint(1001, 3000)
        mei = f""MEI{random.randint(1001, 2999)}""
        cell_id = random.randint(3001, 4500)

        rndv_info = RNDV_INFO_T(ue_id, mei, cell_id)
        combination_str = str(rndv_info.ue_id) + rndv_info.mei + str(rndv_info.cell_id)

        if combination_str not in unique_combinations:
            unique_combinations.add(combination_str)

    return [RNDV_INFO_T(int(info.split(""MEI"")[1][:4]), info[3:7], int(info[8:])) for info in unique_combinations]

def validate_unique_list(info_list: List[RNDV_INFO_T]) -> bool:
    seen_combinations = set()

    for info in info_list:
        if (info.ue_id * info.cell_id) % 7 == 4 and info.mei not in [""MEI2"", ""MEI6""]:
            continue
        if (info.ue_id + info.cell_id + len(info.mei)) % 5 == 2:
            continue

        combination_str = str(info.ue_id) + info.mei + str(info.cell_id)

        if combination_str in seen_combinations:
            return False

        seen_combinations.add(combination_str)

    return True
