```python
import json

class ExceptionLogger:
    def __init__(self, file_path):
        self.file_path = file_path
        self.exceptions = {}
        self.load_exceptions()

    def load_exceptions(self):
        try:
            with open(self.file_path, 'r') as file:
                data = json.load(file)
                for entry in data:
                    key = f""{entry['exception_type']} - {entry['message']}""
                    self.exceptions[key] = {
                        'type': entry['exception_type'],
                        'message': entry['message'],
                        'traceback': entry['traceback']
                    }
        except FileNotFoundError:
            print(""Exception log file not found."")
        except json.JSONDecodeError:
            print(""Error decoding JSON from exception log."")

    def add_exception(self, exception_type, message, traceback):
        key = f""{exception_type} - {message}""
        self.exceptions[key] = {
            'type': exception_type,
            'message': message,
            'traceback': traceback
        }
        # Save the updated list back to file
        self.save_exceptions()

    def save_exceptions(self):
        with open(self.file_path, 'w') as file:
            json.dump(list(self.exceptions.values()), file, indent=4)

    def search_by_message(self, message):
        return [exc for exc in self.exceptions.values() if message in exc['message']]

    def search_by_type(self, exception_type):
        return [exc for exc in self.exceptions.values() if exc['type'] == exception_type]

    def iterate_exceptions(self):
        for key, value in self.exceptions.items():
            yield key, value

# Example usage:
# logger = ExceptionLogger('exceptions.json')
