import random

def generate_random_array(size, min_val, max_val, seed=None):
    if size <= 0:
        raise ValueError(""Size must be greater than zero."")

    # Set the seed for randomness if provided
    if seed is not None:
        random.seed(seed)

    try:
        # Attempt to allocate memory for the array
        arr = [None] * size

        # Fill the array with random integers within the specified range
        for i in range(size):
            arr[i] = random.randint(min_val, max_val)

        # Validate that all elements are within the specified range
        if not all(min_val <= x <= max_val for x in arr):
            raise ValueError(""Array contains values out of the specified range."")

        return arr

    except MemoryError:
        raise MemoryError(""Memory allocation failed during array creation."")

# Example usage:
# random_array = generate_random_array(10, 1, 100, seed=42)
