import argparse
import sys

def count_lines(file_path):
    try:
        with open(file_path, 'r') as file:
            return sum(1 for line in file)
    except Exception as e:
        print(f""Error reading {file_path}: {e}"")
        return None

def print_manpage(file_path):
    try:
        with open(file_path, 'r') as file:
            content = file.read()
            print(content)
    except Exception as e:
        print(f""Error printing manpage from {file_path}: {e}"")

def extract_content(file_path, keyword=None):
    try:
        with open(file_path, 'r') as file:
            lines = file.readlines()
            if keyword:
                return [line for line in lines if keyword in line]
            else:
                return lines
    except Exception as e:
        print(f""Error extracting content from {file_path}: {e}"")
        return None

def main():
    parser = argparse.ArgumentParser(description=""Perform operations on text files."")
    parser.add_argument('operation', choices=['count_lines', 'print_manpage', 'extract_content'], help=""Operation to perform"")
    parser.add_argument('file_path', type=str, help=""Path to the file"")
    parser.add_argument('--keyword', type=str, help=""Keyword for extracting content"", default=None)

    args = parser.parse_args()

    if args.operation == 'count_lines':
        lines_count = count_lines(args.file_path)
        if lines_count is not None:
            print(f""Number of lines: {lines_count}"")

    elif args.operation == 'print_manpage':
        print_manpage(args.file_path)

    elif args.operation == 'extract_content':
        content = extract_content(args.file_path, args.keyword)
        if content is not None:
            for line in content:
                print(line.strip())

if __name__ == ""__main__"":
    main()
