import numpy as np

def create_random_float_array(size, min_value, max_value, seed=None):
    if size <= 0:
        raise ValueError(""Size must be greater than zero."")

    # Seed the random number generator if a seed is provided
    if seed is not None:
        np.random.seed(seed)

    try:
        # Generate an array of random floats
        arr = np.random.uniform(min_value, max_value, size)

        # Validate that all elements are within the specified range
        if np.all((arr >= min_value) & (arr <= max_value)):
            return arr
        else:
            raise ValueError(""Generated values are out of the specified range."")

    except MemoryError:
        raise MemoryError(""Memory allocation failed while creating the array."")

