import wave

class WavMetadata:
    def __init__(self, sample_rate=None, bit_depth=None, channels=None):
        self.sample_rate = sample_rate
        self.bit_depth = bit_depth
        self.channels = channels

def extract_wav_metadata(file_path):
    supported_sample_rates = {44100, 48000, 88200, 96000}

    try:
        with wave.open(file_path, 'rb') as wav_file:
            sample_rate = wav_file.getframerate()
            bit_depth = wav_file.getsampwidth() * 8
            channels = wav_file.getnchannels()

            if sample_rate not in supported_sample_rates:
                return ""Error: Unsupported sample rate.""

            if bit_depth not in range(1, 33):  # Standard WAV range for bit depths is 1 to 32 bits.
                return ""Error: Unsupported bit depth.""

            if channels not in {1, 2}:
                return ""Error: Unsupported number of channels.""

            metadata = WavMetadata(sample_rate=sample_rate, bit_depth=bit_depth, channels=channels)

            return {
                'sample_rate': metadata.sample_rate,
                'bit_depth': metadata.bit_depth,
                'channels': metadata.channels
            }
    except wave.Error as e:
        return f""Error: {str(e)}""
