import numpy as np

def generate_random_float_array(size, min_val, max_val, seed=None):
    try:
        if seed is not None:
            np.random.seed(seed)

        # Generate random floating-point numbers
        array = np.random.uniform(min_val, max_val, size)

        # Verify all elements are within the designated range
        if np.all((array >= min_val) & (array <= max_val)):
            return array
        else:
            raise ValueError(""Generated values are out of bounds"")

    except MemoryError as e:
        print(""Memory allocation error:"", e)
        return None

