### Python Code: Cache Management and File Hashing

```python
import hashlib
import json
import os

def read_config(config_path):
    with open(config_path, 'r') as file:
        config = json.load(file)
    return config

def compute_md5(file_path):
    hash_md5 = hashlib.md5()
    with open(file_path, ""rb"") as f:
        for chunk in iter(lambda: f.read(4096), b""""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def manage_cache(directory, config_file):
    config = read_config(os.path.join(directory, config_file))
    cache_directory = os.path.join(directory, ""cache"")

    if not os.path.exists(cache_directory):
        os.makedirs(cache_directory)

    for file in config['files_to_hash']:
        full_path = os.path.join(directory, file)
        if os.path.isfile(full_path):
            md5_hash = compute_md5(full_path)
            print(f""File: {file}, MD5 Hash: {md5_hash}"")

if __name__ == ""__main__"":
    manage_cache('/path/to/directory', 'config.json')
```

