import random

class SignalMeasurement:
    def __init__(self, frequency, power_level, signal_strength):
        self.frequency = frequency
        self.power_level = power_level
        self.signal_strength = signal_strength

class NetworkComponent:
    def __init__(self):
        self.optimized_data = []

    def optimize_network_traffic(self, measurements):
        for measurement in measurements:
            optimized_measurement = self._apply_optimization(measurement)
            self.optimized_data.append(optimized_measurement)

    def _apply_optimization(self, measurement):
        optimized_frequency = round(measurement.frequency * 1.2)
        optimized_power_level = min(max(measurement.power_level + 3, 1), 10)

        return SignalMeasurement(optimized_frequency, optimized_power_level, measurement.signal_strength)

def create_and_populate_signal_measurement_list(num_measurements):
    measurements = []

    for _ in range(num_measurements):
        frequency = random.uniform(100, 1000)

        power_levels_range_low = max(frequency // 50, 1) if frequency > 50 else random.randint(1, 4)

        power_levels_range_high = min(power_levels_range_low * 3 + (random.randint(-2, 2) * (power_levels_range_low // 5)), 9) 

        power_level_options = list(range(power_levels_range_low, power_levels_range_high + 1))

        selected_power_level_option_index = random.choice(range(len(power_level_options)))

        signal_strength = random.randint(1, 8)

        measurement = SignalMeasurement(frequency, power_level_options[selected_power_level_option_index], signal_strength)

        measurements.append(measurement)

    return measurements

def main():
    num_measurements = 50
    network_component = NetworkComponent()
    measurements_list = create_and_populate_signal_measurement_list(num_measurements)

    network_component.optimize_network_traffic(measurements_list)

    print(""Generated Signal Measurements:"")
    for measurement in network_component.optimized_data:
        print(f""Frequency: {measurement.frequency}, Power Level: {measurement.power_level}, Signal Strength: {measurement.signal_strength}"")

if __name__ == ""__main__"":
    main()
