import os
import struct
import time
from datetime import datetime

def generate_ethernet_packets(num_packets, src_mac, dst_mac):
    if num_packets <= 0:
        raise ValueError(""Number of packets must be greater than zero."")

    # Validate MAC addresses format
    mac_pattern = r'^([0-9A-Fa-f]{2}[:-]){5}([0-9A-Fa-f]{2})$'
    for mac in (src_mac, dst_mac):
        if not re.match(mac_pattern, mac):
            raise ValueError(""Invalid MAC address format."")

    def random_payload(size):
        return os.urandom(size)

    packets = []

    for _ in range(num_packets):
        payload_size = randint(64, 1500)
        timestamp = datetime.now()

        packet_structure = {
            'src_mac': src_mac,
            'dst_mac': dst_mac,
            'payload': random_payload(payload_size),
            'timestamp': timestamp
        }

        packets.append(packet_structure)

    return packets

# Example usage:
# packets = generate_ethernet_packets(5, ""00:1A:2B:3C:4D:5E"", ""FE:DC:BA:98:76:54"")
