import os
import gzip
import hashlib
from mimetypes import guess_type

class GzipFileHandler:
    def __init__(self):
        self.supported_mime_types = ('text/plain', 'application/gzip')

    def validate_file_path(self, file_path):
        if not os.path.exists(file_path):
            raise FileNotFoundError(f""File {file_path} does not exist."")
        if not os.access(file_path, os.R_OK):
            raise PermissionError(f""Cannot read file {file_path}."")

    def check_mime_type(self, file_path):
        mime_type, _ = guess_type(file_path)
        if mime_type not in self.supported_mime_types:
            raise ValueError(f""MIME type {mime_type} is not supported for Gzip compression."")

    def compress_file(self, input_file_path, output_file_path, level=9, null_compression=False):
        self.validate_file_path(input_file_path)
        self.check_mime_type(input_file_path)

        if null_compression:
            with open(output_file_path, 'wb') as f_out:
                f_out.write(b'')
            return

        try:
            with open(input_file_path, 'rb') as f_in, gzip.open(output_file_path, 'wb', compresslevel=level) as f_out:
                f_out.writelines(f_in)
            self.generate_checksum(output_file_path)
        except IOError as e:
            raise Exception(f""File operation failed: {e}"")

    def decompress_file(self, input_file_path, output_file_path):
        if not gzip.fileobj.is_gzipfile(input_file_path):
            raise ValueError(""The file is not a valid Gzip-compressed file."")

        try:
            with gzip.open(input_file_path, 'rb') as f_in, open(output_file_path, 'wb') as f_out:
                original_data = f_in.read()
                f_out.write(original_data)

            if not self.verify_checksum(input_file_path):
                raise ValueError(""Checksum verification failed."")

        except IOError as e:
            raise Exception(f""File operation failed: {e}"")

    def generate_checksum(self, file_path):
        hasher = hashlib.md5()
        with open(file_path, 'rb') as f:
            buf = f.read(8192)
            while buf:
                hasher.update(buf)
                buf = f.read(8192)
        return hasher.hexdigest()

    def verify_checksum(self, file_path, expected_checksum=None):
        if expected_checksum is None:
            # In a real-world scenario, this should be fetched from metadata or storage
            expected_checksum = self.generate_checksum(file_path)

        current_checksum = self.generate_checksum(file_path)
        return current_checksum == expected_checksum

# Example Usage
handler = GzipFileHandler()
try:
    handler.compress_file('example.txt', 'example.txt.gz', level=5, null_compression=False)
    handler.decompress_file('example.txt.gz', 'decompressed_example.txt')
except Exception as e:
    print(e)
