import json
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives import padding

class DESKeyManager:
    def __init__(self):
        self.keys = {}

    def store_key(self, key_id, key_value):
        self.keys[key_id] = key_value.encode()[:8]  # Ensure key length matches DES requirements

    def retrieve_key(self, key_id):
        return self.keys.get(key_id)

def validate_oauth_token(token):
    required_fields = ['access_token', 'expires_in', 'token_type']
    if not all(field in token for field in required_fields):
        raise ValueError(""Token missing required fields"")

    if not (token['token_type'] == ""Bearer"" and isinstance(token['expires_in'], int) and token['expires_in'] > 0):
        raise ValueError(""Invalid token type or negative expiration"")

def encrypt_data(data, mode='ECB', key=None, iv=None):
    valid_modes = ['ECB', 'EDE', 'EDE3', 'CFB']
    if mode not in valid_modes:
        raise ValueError(""Invalid cipher mode"")

    des_key = key.encode()[:8]  # Ensure key length matches DES requirements
    des_cipher = algorithms.TripleDES(des_key)

    match mode:
        case ""ECB"":
            iv = b'\x00'*8 if iv is None else iv
            cipher_mode = modes.ECB()
        case ""EDE"":
            iv = b'\x00'*8 if iv is None else iv
            cipher_mode = modes.ECB()  # EDE mode uses ECB setup in cryptography
        case ""EDE3"":
            iv = b'\x00'*8 if iv is None else iv
            cipher_mode = modes.ECB()
        case ""CFB"":
            if not iv:
                raise ValueError(""IV required for CFB mode"")
            cipher_mode = modes.CFB(iv)

    encryptor = Cipher(des_cipher, cipher_mode, backend=default_backend()).encryptor()
    padder = padding.PKCS7(64).padder()

    padded_data = padder.update(data.encode()) + padder.finalize()
    encrypted_data = encryptor.update(padded_data) + encryptor.finalize()

    return encrypted_data

def unified_function(token, key_manager, cipher_mode='ECB', enable_encryption=True):
    try:
        validate_oauth_token(token)

        if 'refresh_token' in token:
            additional_fields = ['refresh_token']
        else:
            additional_fields = []

        if not all(field in token for field in additional_fields):
            raise ValueError(""Token missing optional but specified fields"")

        if enable_encryption:
            key_id = ""default_key""
            des_key = key_manager.retrieve_key(key_id)
            if not des_key:
                raise KeyError(""Key not found in Key Manager"")

            encrypted_token = encrypt_data(json.dumps(token), mode=cipher_mode, key=des_key.decode())
            return encrypted_token

        return json.dumps(token)

    except (ValueError, KeyError) as e:
        print(f""Error: {e}"")
        return None

# Usage Example
if __name__ == ""__main__"":
    token_response = {
        ""access_token"": ""abc123"",
        ""expires_in"": 3600,
        ""token_type"": ""Bearer"",
        ""refresh_token"": ""xyz789""
    }

    key_manager = DESKeyManager()
    key_manager.store_key(""default_key"", ""mydeskey123"")  # Ensure the key is at least 8 bytes

    encrypted_response = unified_function(token_response, key_manager, cipher_mode='CFB', enable_encryption=True)
    if encrypted_response:
        print(""Encrypted Token Response:"", encrypted_response)

    decrypted_response = unified_function(token_response, key_manager, cipher_mode='ECB', enable_encryption=False)
    if decrypted_response:
        print(""Token Response:"", json.loads(decrypted_response))
```

