def check_sort_order(arr):
    def is_ascending(lst):
        return all(lst[i] <= lst[i + 1] for i in range(len(lst) - 1))

    def is_descending(lst):
        return all(lst[i] >= lst[i + 1] for i in range(len(lst) - 1))

    if is_ascending(arr):
        return ""Ascending""
    elif is_descending(arr):
        return ""Descending""
    else:
        return ""Neither""

# Example usage:
