from typing import List
import graphene

def generate_graphql_endpoint(
    field_names: List[str], 
    base_api_url: str, 
    graphql_client_instance
):

    class Query(graphene.ObjectType):
        def __init__(self, fields):
            self.fields = fields

        def resolve_fields(self, info):
            # Implement logic to resolve each field as needed.
            return {field: f""Value of {field}"" for field in self.fields}

    valid_field_names = {""name"", ""age"", ""email""}  # Example set of valid fields
    invalid_fields = [field for field in field_names if field not in valid_field_names]

    if invalid_fields:
        raise ValueError(f""Invalid field names provided: {', '.join(invalid_fields)}"")

    query_type = Query(field_names)
    schema = graphene.Schema(query=query_type)

    class GraphQLClientWrapper:
        def __init__(self, client_instance, schema):
            self.client_instance = client_instance
            self.schema = schema

        def execute_query(self, query_string, variables=None):
            return self.client_instance.execute(
                self.schema,
                query=query_string,
                variable_values=variables,
                operation_name=None  # You can modify this based on your requirements.
            )

    wrapped_client = GraphQLClientWrapper(graphql_client_instance, schema)

    # Set the base URL for the client (assuming it has a method to set URL)
    wrapped_client.client_instance.set_url(base_api_url) 

    return wrapped_client

# Example usage
# Assuming 'client' is an instance of a hypothetical GraphQL client class
# endpoint = generate_graphql_endpoint([""name"", ""age""], ""https://api.example.com/graphql"", client)
